CREATE DATABASE IF NOT EXISTS student_record_management CHARACTER SET utf8mb4 COLLATE utf8mb4_unicode_ci;
USE student_record_management;
CREATE TABLE users (user_id INT AUTO_INCREMENT PRIMARY KEY, username VARCHAR(60) NOT NULL, email VARCHAR(254) NOT NULL, password_hash CHAR(64) NOT NULL, department VARCHAR(100) NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_users_username UNIQUE(username), CONSTRAINT uq_users_email UNIQUE(email));
CREATE TABLE students (student_id INT AUTO_INCREMENT PRIMARY KEY, roll_no VARCHAR(50) NOT NULL, name VARCHAR(150) NOT NULL, department VARCHAR(100) NOT NULL, year VARCHAR(30) NOT NULL, batch VARCHAR(30) NOT NULL, semester VARCHAR(30) NOT NULL, mobile VARCHAR(25) NOT NULL, email VARCHAR(254) NOT NULL, uploaded_by INT NOT NULL, created_at TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT uq_student_roll_per_user UNIQUE(uploaded_by, roll_no), CONSTRAINT fk_students_user FOREIGN KEY(uploaded_by) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE TABLE upload_history (upload_id INT AUTO_INCREMENT PRIMARY KEY, user_id INT NOT NULL, file_name VARCHAR(255) NOT NULL, department VARCHAR(100) NOT NULL, batch VARCHAR(30) NOT NULL, year VARCHAR(30) NOT NULL, total_records INT NOT NULL CHECK(total_records > 0), upload_date TIMESTAMP NOT NULL DEFAULT CURRENT_TIMESTAMP, CONSTRAINT fk_history_user FOREIGN KEY(user_id) REFERENCES users(user_id) ON DELETE CASCADE);
CREATE INDEX idx_students_owner_filters ON students(uploaded_by, department, year, batch, semester);
